namespace NinjaTrader.Core {public static class Globals {public static DateTime MaxDate=DateTime.MaxValue;}}

namespace NinjaTrader.Cbi {

 public enum Provider {Simulator,Playback,Live} public enum ConnectionStatus {Connected,Disconnected} public class Connection {public ConnectionStatus Status=ConnectionStatus.Connected;}

 public enum Currency {Usd} public enum MarketPosition {Long,Short,Flat} public enum OrderAction {Buy,Sell,SellShort,BuyToCover} public enum OrderType {Market,Limit,StopMarket,StopLimit,MIT,Unsupported} public enum OrderEntry {Manual} public enum TimeInForce {Day,Gtd}

 public enum OrderState {Submitted,Accepted,Working,TriggerPending,Cancelled,Rejected,Filled,PartFilled} public enum AccountItem {RealizedProfitLoss,UnrealizedProfitLoss,NetLiquidation,SodLiquidatingValue}

 public class Instrument {public string FullName="MES 12-26";} public class Position {public Instrument Instrument;public int Quantity;public MarketPosition MarketPosition;}

 public class Order {public Account Account;public Instrument Instrument;public string Name,Oco,OrderId;public OrderAction OrderAction;public OrderType OrderType;public OrderEntry OrderEntry;public TimeInForce TimeInForce;public DateTime Gtd;public OrderState OrderState;public int Quantity,Filled,QuantityChanged;public double AverageFillPrice;public double LimitPrice,StopPrice,LimitPriceChanged,StopPriceChanged;public static bool IsTerminalState(OrderState s){return s==OrderState.Filled||s==OrderState.Rejected||s==OrderState.Cancelled;}}

 public class OrderEventArgs:EventArgs {public Order Order;public OrderState OrderState;public int Quantity,Filled;public string OrderId;public double LimitPrice,StopPrice;}

 // Deliberately fake sink: only counters and in-memory synthetic collections. No NT assembly or brokerage access.

 public class Account {

  public string Name;public Provider Provider=Provider.Simulator;public Connection Connection=new Connection();public Currency Denomination=Currency.Usd;

  public List<Position> Positions=new List<Position>();public List<Order> Orders=new List<Order>();public event EventHandler<OrderEventArgs> OrderUpdate;

  public double Pnl,Equity=50000;public bool DropSubmitCallback,HideSubmittedOrder,AcceptThenThrow;public Order LastAccepted,LastFlattenClose;public ManualResetEvent GetEntered,GetRelease;public int GetBlock;public bool SilentAcceptedFlatten;public int Submits,Changes,Cancels,Flattens;public bool ThrowSubmit,ThrowCancel,ThrowFlatten;public ManualResetEvent CreateEntered,CreateRelease,SubmitEntered,SubmitRelease;public bool AsyncCancel,NoopFlatten,FlattenWorkingBeforeThrow;

  public double Get(AccountItem i,Currency c){if(Interlocked.Exchange(ref GetBlock,0)==1){GetEntered.Set();GetRelease.WaitOne();}return i==AccountItem.RealizedProfitLoss?Pnl:i==AccountItem.UnrealizedProfitLoss?0:Equity;}

  public Order CreateOrder(Instrument i,OrderAction a,OrderType t,OrderEntry e,TimeInForce tif,int q,double l,double s,string oco,string n,DateTime g,object ignored){if(CreateEntered!=null){CreateEntered.Set();CreateRelease.WaitOne();}return new Order {Account=this,Instrument=i,OrderAction=a,OrderType=t,OrderEntry=e,TimeInForce=tif,Quantity=q,LimitPrice=l,StopPrice=s,Oco=oco,Name=n,Gtd=g};}

  public void Submit(Order[] orders){if(SubmitEntered!=null){SubmitEntered.Set();SubmitRelease.WaitOne();}if(ThrowSubmit)throw new InvalidOperationException("Synthetic submit error");foreach(var o in orders){if(!HideSubmittedOrder){lock(Orders)Orders.Add(o);}LastAccepted=o;o.OrderState=OrderState.Working;Interlocked.Increment(ref Submits);if(!DropSubmitCallback)Emit(o);if(AcceptThenThrow)throw new TimeoutException("synthetic accepted then timeout");}}

  public void Change(Order[] orders){foreach(var o in orders){o.Quantity=o.QuantityChanged;o.LimitPrice=o.LimitPriceChanged;o.StopPrice=o.StopPriceChanged;Interlocked.Increment(ref Changes);Emit(o);}}

  public void Cancel(Order[] orders){if(AsyncCancel){Interlocked.Add(ref Cancels,orders.Length);return;}if(ThrowCancel)throw new InvalidOperationException("Synthetic cancel error");foreach(var o in orders){o.OrderState=OrderState.Cancelled;Interlocked.Increment(ref Cancels);Emit(o);}}

  public void Flatten(Instrument[] inst){if(NoopFlatten){Interlocked.Increment(ref Flattens);return;}if(ThrowFlatten){if(SilentAcceptedFlatten){LastFlattenClose=CreateOrder(inst[0],OrderAction.Sell,OrderType.Market,OrderEntry.Manual,TimeInForce.Day,2,0,0,"","SyntheticInvisibleFlatten",DateTime.MaxValue,null);LastFlattenClose.OrderState=OrderState.Working;}if(FlattenWorkingBeforeThrow){var pending=CreateOrder(inst[0],OrderAction.Sell,OrderType.Market,OrderEntry.Manual,TimeInForce.Day,2,0,0,"","SyntheticPendingFlatten",DateTime.MaxValue,null);pending.OrderState=OrderState.Working;Orders.Add(pending);Emit(pending);}throw new InvalidOperationException("Synthetic flatten error");}Interlocked.Increment(ref Flattens);foreach(var o in Orders.ToArray())Cancel(new[]{o});lock(Positions)Positions.Clear();var fake=CreateOrder(inst[0],OrderAction.Sell,OrderType.Market,OrderEntry.Manual,TimeInForce.Day,1,0,0,"","SyntheticFlatten",DateTime.MaxValue,null);fake.OrderState=OrderState.Submitted;Emit(fake);}

  public void EmitCaptured(Order o,OrderState state,int quantity,int filled,string provider){var h=OrderUpdate;if(h!=null)h(this,new OrderEventArgs{Order=o,OrderId=provider,OrderState=state,Quantity=quantity,Filled=filled,LimitPrice=o.LimitPrice,StopPrice=o.StopPrice});}
  public void Emit(Order o){var h=OrderUpdate;if(h!=null)h(this,new OrderEventArgs {Order=o,OrderId=o.OrderId,OrderState=o.OrderState,Quantity=o.Quantity,Filled=o.Filled,LimitPrice=o.LimitPrice,StopPrice=o.StopPrice});}

 }

}

class EngineSafetyTests {

 static int Main(string[] args){var names=args.Length==0?new[]{"LostFillLaggedPositionBlocksNewEntry","FuturePartialFillCannotFreeReservation","SilentFlattenThrowBlocksNewExit","SameFilledOlderWorkingDoesNotDowngradeTerminalEvidence","FlatRiskLatchDoesNotPermanentlyTrapSession","PartialQuantityDivergenceVisible","LostProtectionSubmitAckCoverageUnknown","FutureExitFillCannotFreeCloseReservation","ProtectionReturnIsNotAcceptanceAndLateAckResolves","QuantityDivergenceVisibleAfterExistingRiskLatch"}:args[0].Split(',');int pass=0,fail=0;foreach(var name in names)try{typeof(EngineSafetyTests).GetMethod(name,System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,null);Console.WriteLine("PASS "+name);pass++;}catch(Exception ex){Console.WriteLine("FAIL "+name+" "+(ex.InnerException??ex));fail++;}Console.WriteLine("TOTAL pass="+pass+" fail="+fail);return fail==0?0:1;}

 static NinjaTrader.Cbi.Instrument inst=new NinjaTrader.Cbi.Instrument();

 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}

 static void Wait(Func<bool> condition,string message){for(int i=0;i<300;i++){if(condition())return;Thread.Sleep(10);}throw new Exception("timeout: "+message);}

 static NinjaTrader.Cbi.Order LeaderOrder(NinjaTrader.Cbi.Account a,NinjaTrader.Cbi.OrderAction action,string oco="",int qty=2){var o=a.CreateOrder(inst,action,NinjaTrader.Cbi.OrderType.Limit,NinjaTrader.Cbi.OrderEntry.Manual,NinjaTrader.Cbi.TimeInForce.Day,qty,100,0,oco,"SyntheticLeader",DateTime.MaxValue,null);o.OrderState=NinjaTrader.Cbi.OrderState.Submitted;return o;}

 static NinjaTrader.Cbi.Account Acc(string name){return new NinjaTrader.Cbi.Account{Name=name};}

 static CopierEngine Arm(NinjaTrader.Cbi.Account l,NinjaTrader.Cbi.Account a,Action<AccountTelemetry> tele=null,Action<string,string> persist=null){var e=new CopierEngine(s=>{},tele??(t=>{}),(attached,s)=>{},persist??((n,r)=>{}));e.Start(l,inst,new[]{Tuple.Create(a,new RiskSettings{MaxContracts=10,Target=100},new RiskLatch())});Wait(()=>e.EntriesArmed,"arm");return e;}

 static void Drain(CopierEngine e){var f=typeof(CopierEngine).GetField("worker",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);var w=(SerialWorker)f.GetValue(e);var done=new ManualResetEvent(false);w.Post(()=>done.Set());Check(done.WaitOne(3000),"drain");}

 static void Fill(NinjaTrader.Cbi.Account a,int qty,bool position=true){var o=a.Orders[0];o.Filled=qty;o.OrderState=o.Quantity==qty?NinjaTrader.Cbi.OrderState.Filled:NinjaTrader.Cbi.OrderState.PartFilled;if(position)a.Positions.Add(new NinjaTrader.Cbi.Position{Instrument=inst,Quantity=qty,MarketPosition=NinjaTrader.Cbi.MarketPosition.Long});a.Emit(o);}

 static CopyLink OnlyEntry(CopierEngine e){return ((Dictionary<string,List<CopyLink>>)typeof(CopierEngine).GetField("links",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(e)).Values.SelectMany(x=>x).First(x=>!x.Exit);}

 static EngineAccount Follower(CopierEngine e){return OnlyEntry(e).Follower;}

 static void LostFillLaggedPositionBlocksNewEntry(){var l=Acc("lost fill lag l");var a=Acc("lost fill lag a");AccountTelemetry latest=null;using(var e=new CopierEngine(s=>{},x=>latest=x,(b,s)=>{},(n,r)=>{})){e.Start(l,inst,new[]{Tuple.Create(a,new RiskSettings{MaxContracts=2},new RiskLatch())});Wait(()=>e.EntriesArmed,"arm");l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy));Drain(e);var o=a.Orders[0];o.Filled=2;o.OrderState=NinjaTrader.Cbi.OrderState.Filled;e.Poll();Drain(e);l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy));Drain(e);Console.WriteLine("lost fill callback + position lag: submits="+a.Submits+" ledger="+OnlyEntry(e).ObservedFilled+" state="+latest.State);Check(a.Submits==1&&!latest.Following,"unobserved mutable provider fill must block new entry, not free capacity");}}

 static void FuturePartialFillCannotFreeReservation(){var l=Acc("future reservation l");var a=Acc("future reservation a");using(var e=new CopierEngine(s=>{},x=>{},(b,s)=>{},(n,r)=>{})){e.Start(l,inst,new[]{Tuple.Create(a,new RiskSettings{MaxContracts=4},new RiskLatch())});Wait(()=>e.EntriesArmed,"arm");l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);Fill(a,2);Drain(e);a.Orders[0].Filled=4; // callback and Position still lag; ledger knows only 2.

 l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",2));Drain(e);Console.WriteLine("future mutable Filled=4 observed=2 cap=4 submits="+a.Submits+" cancelled="+a.Cancels);Check(a.Submits==1,"mutable future Filled must not release pending reservation before immutable evidence");}}

 static void SilentFlattenThrowBlocksNewExit(){var l=Acc("flatten ambiguous l");var a=Acc("flatten ambiguous a");using(var e=Arm(l,a)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy));Drain(e);Fill(a,2);Drain(e);a.ThrowFlatten=true;a.SilentAcceptedFlatten=true; // timeout after silent provider accept, neither order collection nor callback exposes close yet.

 e.Flatten(new[]{a},inst);Drain(e);l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Sell,"ambiguous close"));Drain(e);Console.WriteLine("Flatten threw without order evidence: newExitSubmits="+(a.Submits-1)+" flattening="+Follower(e).Flattening+" locked="+Follower(e).Latch.Locked);bool prevented=a.Submits==1&&Follower(e).Flattening;

 if(a.Submits>1){var mirrored=a.Orders[1];mirrored.Filled=2;mirrored.OrderState=NinjaTrader.Cbi.OrderState.Filled;a.Positions.Clear();a.Emit(mirrored);Drain(e);var hidden=a.LastFlattenClose;hidden.Filled=2;hidden.OrderState=NinjaTrader.Cbi.OrderState.Filled;a.Positions.Add(new NinjaTrader.Cbi.Position{Instrument=inst,Quantity=2,MarketPosition=NinjaTrader.Cbi.MarketPosition.Short});a.Emit(hidden);Drain(e);Console.WriteLine("silent accepted Flatten + mirror both Sell2 => synthetic position="+CopierEngine.Position(a,inst));}

 Check(prevented,"exception is ambiguous acceptance, block concurrent exit until explicit reconciliation");}}

 static void SameFilledOlderWorkingDoesNotDowngradeTerminalEvidence(){var l=Acc("old state l");var a=Acc("old state a");AccountTelemetry latest=null;using(var e=Arm(l,a,t=>latest=t)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy));Drain(e);Fill(a,2);Drain(e);var o=a.Orders[0];o.OrderState=NinjaTrader.Cbi.OrderState.Working;a.Emit(o);Drain(e);Console.WriteLine("Filled->oldWorking cumulative=2 observedState="+OnlyEntry(e).ObservedState+" following="+latest.Following+" locked="+latest.Locked+" state="+latest.State);Check(OnlyEntry(e).ObservedState==NinjaTrader.Cbi.OrderState.Filled&&latest.Locked&&a.Cancels==0,"older Working must retain terminal Filled, flag ambiguity, and not issue a cancellation of proven terminal work");}}

 static void FlatRiskLatchDoesNotPermanentlyTrapSession(){var l=Acc("flat latch l");var a=Acc("flat latch a");int locks=0;using(var e=Arm(l,a,null,(n,r)=>locks++)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy));Drain(e);a.Pnl=100;e.Poll();Drain(e);Drain(e);var f=Follower(e);Check(locks==1&&f.Latch.Locked&&a.Cancels==1&&a.Orders[0].OrderState==NinjaTrader.Cbi.OrderState.Cancelled&&CopierEngine.Position(a,inst)==0,"precondition: durable target latch, zero executed exposure, cancellation acknowledged");Console.WriteLine("flat risk latch knownFilled="+OnlyEntry(e).ObservedFilled+" allOrdersTerminal=true durableLocks="+locks+" CanClose="+e.CanClose());e.StopFlat();Drain(e);Console.WriteLine("after StopFlat attached="+e.Attached+" latch="+f.Latch.Locked);Check(!e.Attached&&f.Latch.Locked,"clean terminal zero-exposure session should detach without clearing durable authorization latch");}}

 static void PartialQuantityDivergenceVisible(){var l=Acc("partial divergence l");var a=Acc("partial divergence a");AccountTelemetry latest=null;using(var e=Arm(l,a,t=>latest=t)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);Fill(a,2);Drain(e);a.Orders[0].OrderState=NinjaTrader.Cbi.OrderState.Filled;a.Emit(a.Orders[0]);Drain(e);e.Poll();Drain(e);Console.WriteLine("terminal Filled but intended=4 observed=2 telemetry State="+latest.State+" Position="+latest.Position+" Reason="+latest.Reason);Check(((latest.State+latest.Reason).IndexOf("partial",StringComparison.OrdinalIgnoreCase)>=0||(latest.State+latest.Reason).IndexOf("divergen",StringComparison.OrdinalIgnoreCase)>=0)&&latest.Reason.Contains("expected=4")&&latest.Reason.Contains("observed=2")&&a.Submits==1&&OnlyEntry(e).ObservedFilled==2,"expected=4/observed=2 discrepancy must be surfaced with no fabricated evidence, makeup or chase");}}

 static void LostProtectionSubmitAckCoverageUnknown(){var l=Acc("exit ack l");var a=Acc("exit ack a");AccountTelemetry latest=null;using(var e=Arm(l,a,t=>latest=t)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy));Drain(e);Fill(a,2);Drain(e);a.DropSubmitCallback=true;a.HideSubmittedOrder=true;l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Sell,"silent protection"));Drain(e);e.Poll();Drain(e);Console.WriteLine("exit ack lost submits="+a.Submits+" orders="+a.Orders.Count+" state="+latest.State+" locked="+latest.Locked+" reason="+latest.Reason);Check((latest.State+latest.Reason).IndexOf("unconfirm",StringComparison.OrdinalIgnoreCase)>=0||(latest.State+latest.Reason).IndexOf("uncertain",StringComparison.OrdinalIgnoreCase)>=0||(latest.State+latest.Reason).IndexOf("coverage",StringComparison.OrdinalIgnoreCase)>=0,"missing protective acceptance evidence must be displayed unconfirmed, not generic Active");}}

 static void FutureExitFillCannotFreeCloseReservation(){var l=Acc("future exit l");var a=Acc("future exit a");using(var e=Arm(l,a)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);Fill(a,4);Drain(e);l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Sell,"first protection",4));Drain(e);var close=a.Orders[1];close.Filled=4;close.OrderState=NinjaTrader.Cbi.OrderState.Filled; // no immutable callback or Position update yet.

 l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Sell,"independent second",4));Drain(e);Check(a.Submits==2,"future terminal exit wrapper cannot free owned reservation for another independent reduction");Check(OnlyEntry(e).ObservedFilled==4,"do not invent entry/exit evidence");}}

 static void ProtectionReturnIsNotAcceptanceAndLateAckResolves(){var l=Acc("acceptance l");var a=Acc("acceptance a");AccountTelemetry latest=null;using(var e=Arm(l,a,t=>latest=t)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy));Drain(e);Fill(a,2);Drain(e);a.DropSubmitCallback=true;a.HideSubmittedOrder=true;l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Sell,"unconfirmed"));Drain(e);e.Poll();Drain(e);var link=((Dictionary<string,List<CopyLink>>)typeof(CopierEngine).GetField("links",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(e)).Values.SelectMany(x=>x).First(x=>x.Exit);Check(!link.AcceptanceConfirmed&&latest.State.Contains("coverage unknown")&&a.Changes==0,"Submit return and mutable Working alone cannot establish acceptance / coverage or permit Change");e.Poll();Drain(e);Check(a.Submits==2&&!e.CanClose(),"unknown protective request retained without retry or detach");a.Emit(a.LastAccepted);Drain(e);e.Poll();Drain(e);Check(link.AcceptanceConfirmed&&!latest.State.Contains("coverage unknown")&&a.Submits==2,"captured late Working acknowledges same request, no catch-up/retry");}}

 static void QuantityDivergenceVisibleAfterExistingRiskLatch(){var l=Acc("latched quantity l");var a=Acc("latched quantity a");AccountTelemetry latest=null;using(var e=Arm(l,a,t=>latest=t)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);Fill(a,2);Drain(e);a.AsyncCancel=true;a.Pnl=100;e.Poll();Drain(e);Check(latest.Locked,"target latch before terminal divergence");a.Orders[0].OrderState=NinjaTrader.Cbi.OrderState.Filled;a.Emit(a.Orders[0]);Drain(e);e.Poll();Drain(e);Check(latest.Reason.Contains("expected=4")&&latest.Reason.Contains("observed=2")&&a.Submits==1,"an existing durable risk latch must not hide terminal expected/observed divergence; no chase");}}

 static void ExplicitManualFlatReconciliationAvailable(){var l=Acc("external flatten l");var a=Acc("external flatten a");using(var e=Arm(l,a)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy));Drain(e);Fill(a,2);Drain(e);a.NoopFlatten=true;e.Flatten(new[]{a},inst);Drain(e);var close=LeaderOrder(a,NinjaTrader.Cbi.OrderAction.Sell);close.OrderState=NinjaTrader.Cbi.OrderState.Filled;close.Filled=2;a.Orders.Add(close);a.Positions.Clear();a.Emit(close);Drain(e);e.Poll();Drain(e);Console.WriteLine("external flatten terminal confirmed position=0 owned="+OnlyEntry(e).ObservedFilled+" canClose="+e.CanClose()+" flattening="+Follower(e).Flattening);e.AcknowledgeFlattenAbandoned(a.Name);Drain(e);Check(Follower(e).Flattening&&!e.CanClose(),"normal abandonment cannot confirm flat / clear risk latch");

 var seam=typeof(CopierEngine).GetMethod("AcknowledgeFlattenConfirmed");Check(seam!=null,"explicit manual verified-flat reconciliation path is missing; do not auto-clear latches");}}

 static void ProductionAllProvidersCannotEnable(){foreach(var provider in new[]{NinjaTrader.Cbi.Provider.Simulator,NinjaTrader.Cbi.Provider.Playback,NinjaTrader.Cbi.Provider.Live}){var l=Acc("all hold l "+provider);var a=Acc("all hold a "+provider);l.Provider=provider;a.Provider=provider;using(var e=new CopierEngine(s=>{},t=>{},(b,s)=>{},(n,r)=>{})){e.Start(l,inst,new[]{Tuple.Create(a,new RiskSettings{MaxContracts=10},new RiskLatch())});Drain(e);e.SetFollowing(a.Name,true);e.Flatten(new[]{a,l},inst);Drain(e);Check(!e.Attached&&!e.EntriesArmed&&a.Flattens==0&&l.Flattens==0&&a.Submits==0,"ordinary compilation cannot arm or flatten any provider");Check(new[]{"start","flattenSelected","flattenAll","batch"}.All(c=>!DashboardSafety.CanExecute(c)),"all UI trading gates held");Console.WriteLine("provider="+provider+" attached=false submits=0 flattens=0");}}}





 // F01 real-event contract regressions. Payload and mutable wrapper deliberately diverge.
 static List<CopyLink> AllLinks(CopierEngine e){return ((Dictionary<string,List<CopyLink>>)typeof(CopierEngine).GetField("links",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(e)).Values.SelectMany(x=>x).ToList();}
 static int EvidenceInt(CopierEngine e,string name,object arg){return (int)typeof(CopierEngine).GetMethod(name,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(e,name=="PendingEntries"?new object[]{arg,null}:new[]{arg});}
 static SerialWorker Queue(CopierEngine e){return (SerialWorker)typeof(CopierEngine).GetField("worker",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(e);}
 static void PayloadEntryFillAndLaggedPosition(){var l=Acc("payload lag l");var a=Acc("payload lag a");using(var e=Arm(l,a)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);var x=OnlyEntry(e);x.Order.Filled=4;x.Order.OrderState=NinjaTrader.Cbi.OrderState.PartFilled;a.AsyncCancel=true;a.EmitCaptured(x.Order,NinjaTrader.Cbi.OrderState.PartFilled,4,2,"event-entry");Drain(e);Check(CopierEngine.Position(a,inst)==0&&x.ObservedFilled==2&&EvidenceInt(e,"OwnedPosition",x.Follower)==2&&EvidenceInt(e,"PendingEntries",x.Follower)==2,"lagged Position and future wrapper must preserve observed2 plus reserved2");Check(x.ExecutionEvidence.Last().Filled==2&&x.ProviderId=="event-entry","entry evidence and identity come from event");e.Poll();Drain(e);l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy));Drain(e);Check(a.Submits==1&&x.ObservedFilled==2,"divergent wrapper cannot free entry capacity or synthesize future fill");}}
 static void PayloadExitFillAndLaggedPosition(){var l=Acc("payload exit lag l");var a=Acc("payload exit lag a");using(var e=Arm(l,a)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);Fill(a,4);Drain(e);l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Sell,"first",4));Drain(e);var x=AllLinks(e).Single(z=>z.Exit);x.Order.Filled=4;x.Order.OrderState=NinjaTrader.Cbi.OrderState.PartFilled;a.EmitCaptured(x.Order,NinjaTrader.Cbi.OrderState.PartFilled,4,2,"event-exit");Drain(e);Check(CopierEngine.Position(a,inst)==4&&x.ObservedFilled==2&&EvidenceInt(e,"OwnedPosition",x.Follower)==2&&x.ReservedQuantity-x.ObservedFilled==2,"lagged Position and future exit wrapper retain owned2/reserved2");Check(x.ExecutionEvidence.Last().ProviderId=="event-exit","exit event identity retained");l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Sell,"independent",4));Drain(e);Check(a.Submits==2,"unobserved exit fills cannot free independent close reservation");}}
 static void ZeroEventFillNeverFallsBackToWrapper(){var l=Acc("payload zero l");var a=Acc("payload zero a");a.AsyncCancel=true;using(var e=Arm(l,a)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);var x=OnlyEntry(e);x.Order.Filled=4;x.Order.OrderState=NinjaTrader.Cbi.OrderState.PartFilled;x.Order.OrderId="future";a.EmitCaptured(x.Order,NinjaTrader.Cbi.OrderState.PartFilled,4,0,null);Drain(e);Check(x.ObservedFilled==0&&EvidenceInt(e,"OwnedPosition",x.Follower)==0&&EvidenceInt(e,"PendingEntries",x.Follower)==4&&string.IsNullOrEmpty(x.ProviderId),"zero/blank event fields are evidence, never populated from wrapper");}}
 static void MutationAfterCallbackQueueBarrier(){var l=Acc("payload barrier l");var a=Acc("payload barrier a");a.AsyncCancel=true;using(var e=Arm(l,a)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);var x=OnlyEntry(e);var entered=new ManualResetEvent(false);var release=new ManualResetEvent(false);Queue(e).Post(()=>{entered.Set();release.WaitOne();});Check(entered.WaitOne(3000),"queue barrier entered");try{var o=x.Order;o.Filled=2;o.OrderState=NinjaTrader.Cbi.OrderState.PartFilled;o.OrderId="wrapper-before";a.EmitCaptured(o,NinjaTrader.Cbi.OrderState.PartFilled,4,2,"event-before");o.Filled=4;o.Quantity=8;o.OrderId="wrapper-after";o.OrderState=NinjaTrader.Cbi.OrderState.Filled;o.LimitPrice=999;o.OrderAction=NinjaTrader.Cbi.OrderAction.Sell;o.OrderType=NinjaTrader.Cbi.OrderType.StopMarket;}finally{release.Set();}Drain(e);Check(x.ObservedFilled==2&&x.ProviderId=="event-before"&&x.ObservedState==NinjaTrader.Cbi.OrderState.PartFilled&&x.ReservedQuantity==4,"callback snapshots survive future wrapper mutation across queue barrier");var captured=x.ExecutionEvidence.Last();Check(captured.Filled==2&&captured.ProviderId=="event-before"&&captured.Quantity==4&&captured.Action==NinjaTrader.Cbi.OrderAction.Buy&&captured.Type==NinjaTrader.Cbi.OrderType.Limit&&captured.Limit==100,"event and unavoidable wrapper metadata frozen before queue");Check(EvidenceInt(e,"OwnedPosition",x.Follower)==2&&EvidenceInt(e,"PendingEntries",x.Follower)==2,"barrier mutation cannot advance fill or release reservation");}}
