 static void LeaderEventIdentityReplacement(bool exit){var l=Acc("leader payload "+exit+" l");var a=Acc("leader payload "+exit+" a");using(var e=Arm(l,a)){if(exit){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);Fill(a,4);Drain(e);}var action=exit?NinjaTrader.Cbi.OrderAction.Sell:NinjaTrader.Cbi.OrderAction.Buy;var first=LeaderOrder(l,action,exit?"event bracket":"",4);first.OrderId="wrapper-future-1";l.EmitCaptured(first,NinjaTrader.Cbi.OrderState.Submitted,4,0,"event-stable");Drain(e);var replacement=LeaderOrder(l,action,exit?"event bracket":"",4);replacement.OrderId="wrapper-future-2";replacement.OrderState=NinjaTrader.Cbi.OrderState.Working;replacement.LimitPrice=99;l.EmitCaptured(replacement,NinjaTrader.Cbi.OrderState.Working,4,0,"event-stable");Drain(e);Check(a.Submits==(exit?2:1)&&a.Changes==1&&!Follower(e).Latch.Locked,"same captured provider ID replacement maps once despite unrelated future wrapper IDs");}}
 static void LeaderBlankEventUsesEventInitialState(){var l=Acc("leader blank payload l");var a=Acc("leader blank payload a");using(var e=Arm(l,a)){var o=LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy);o.OrderId="future-provider";o.OrderState=NinjaTrader.Cbi.OrderState.Working;l.EmitCaptured(o,NinjaTrader.Cbi.OrderState.Submitted,2,0,null);Drain(e);Check(a.Submits==1&&!Follower(e).Latch.Locked,"blank provider admission uses event Submitted not future wrapper state");o.OrderId="another-future";o.LimitPrice=99;l.EmitCaptured(o,NinjaTrader.Cbi.OrderState.Working,2,0,"event-provider");Drain(e);Check(a.Submits==1&&a.Changes==1&&!Follower(e).Latch.Locked,"blank-to-known event transition valid independently of wrapper ID");}}
 static void LeaderEventIdentityBlankRegressionLocks(){var l=Acc("leader blank regression l");var a=Acc("leader blank regression a");using(var e=Arm(l,a)){var o=LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy);o.OrderId="same-wrapper";l.EmitCaptured(o,NinjaTrader.Cbi.OrderState.Submitted,2,0,"event-known");Drain(e);l.EmitCaptured(o,NinjaTrader.Cbi.OrderState.Working,2,0,null);Drain(e);Check(Follower(e).Latch.Locked&&a.Submits==1&&a.Changes==0,"known-to-blank event identity is ambiguous, never wrapper fallback");}}
