 static void FollowerEventIdentityExitReplacement(){FollowerEventIdentityReplacement(true);}
 static void FollowerEventIdentityReplacement(bool exit){var l=Acc("follower payload "+exit+" l");var a=Acc("follower payload "+exit+" a");a.AsyncCancel=true;using(var e=Arm(l,a)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);if(exit){Fill(a,4);Drain(e);l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Sell,"exit identity",4));Drain(e);}var x=AllLinks(e).Single(z=>z.Exit==exit);x.Order.OrderId="wrapper-one";a.EmitCaptured(x.Order,NinjaTrader.Cbi.OrderState.Working,4,0,"event-follower");Drain(e);Check(x.ProviderId=="event-follower","initial follower identity is event payload");var rep=LeaderOrder(a,exit?NinjaTrader.Cbi.OrderAction.Sell:NinjaTrader.Cbi.OrderAction.Buy,"",4);rep.OrderId="wrapper-two";rep.Filled=2;rep.OrderState=NinjaTrader.Cbi.OrderState.PartFilled;lock(a.Orders){a.Orders[a.Orders.IndexOf(x.Order)]=rep;}a.Positions.Clear();a.Positions.Add(new NinjaTrader.Cbi.Position{Instrument=inst,Quantity=2,MarketPosition=NinjaTrader.Cbi.MarketPosition.Long});a.EmitCaptured(rep,NinjaTrader.Cbi.OrderState.PartFilled,4,2,"event-follower");Drain(e);Check(x.Order==rep&&x.Wrappers.Contains(rep)&&x.ProviderId=="event-follower"&&x.ObservedFilled==2&&!x.Follower.Latch.Locked,"replacement event identity preserves one owned link / evidence");}}
 static void FollowerKnownToBlankRetainsFillAndLocks(){var l=Acc("follower blank payload l");var a=Acc("follower blank payload a");a.AsyncCancel=true;using(var e=Arm(l,a)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);var x=OnlyEntry(e);x.Order.OrderId="future-wrapper";a.EmitCaptured(x.Order,NinjaTrader.Cbi.OrderState.Working,4,0,"event-known");Drain(e);x.Order.Filled=2;x.Order.OrderState=NinjaTrader.Cbi.OrderState.PartFilled;a.EmitCaptured(x.Order,NinjaTrader.Cbi.OrderState.PartFilled,4,2,null);Drain(e);Check(x.ProviderId=="event-known"&&x.ObservedFilled==2&&x.ExecutionEvidence.Last().ProviderId==null&&x.Follower.Latch.Locked,"blank event transition locks while preserving captured owned fill, no identity synthesis");}}
 static void UnknownBlankFollowerReplacementIsNotAdopted(){var l=Acc("follower unknown payload l");var a=Acc("follower unknown payload a");a.AsyncCancel=true;using(var e=Arm(l,a)){l.Emit(LeaderOrder(l,NinjaTrader.Cbi.OrderAction.Buy,"",4));Drain(e);var x=OnlyEntry(e);x.Order.OrderId="known-wrapper";a.EmitCaptured(x.Order,NinjaTrader.Cbi.OrderState.Working,4,0,"event-known");Drain(e);var rep=LeaderOrder(a,NinjaTrader.Cbi.OrderAction.Buy,"",4);rep.OrderId="event-known";rep.Filled=2;rep.OrderState=NinjaTrader.Cbi.OrderState.PartFilled;a.EmitCaptured(rep,NinjaTrader.Cbi.OrderState.PartFilled,4,2,null);Drain(e);Check(x.Order!=rep&&!x.Wrappers.Contains(rep)&&x.ObservedFilled==0&&x.Follower.Latch.Locked,"blank event cannot adopt unknown wrapper merely because future wrapper ID matches");}}
